(function () {
'use strict';
const M = GF.math;
const clamp = M.clamp, dist = M.dist, TAU = M.TAU, makeRng = M.makeRng;

const RING = 120;
const DRAIN = 100 / 65;

const game = new GF.Game({
  id: 'lumen-current',
  title: 'Lumen Current: Signal Garden',
  width: 960,
  height: 540,
  palette: ['#050b14', '#0e2233', '#3ef2c0', '#ffd166'],
  background: '#050b14',
  seed: 1337
});

const play = {
  init() {
    const W = 960, H = 540;
    const rng = makeRng((game.seed ^ 0x9e37) >>> 0);
    this.veins = [];
    for (let i = 0; i < 12; i++) {
      const pts = [];
      let x = 40 + rng() * (W - 80), y = 100 + rng() * (H - 140);
      pts.push([x, y]);
      const n = 3 + ((rng() * 3) | 0);
      for (let j = 0; j < n; j++) {
        x = clamp(x + (rng() - 0.5) * 280, 20, W - 20);
        y = clamp(y + (rng() - 0.5) * 200, 90, H - 20);
        pts.push([x, y]);
      }
      this.veins.push({ pts: pts, phase: rng() * TAU });
    }
    this.motesFar = [];
    this.motesNear = [];
    for (let i = 0; i < 44; i++) this.motesFar.push({ x: rng() * W, y: rng() * H, r: 1 + rng() * 1.6, s: 6 + rng() * 10, ph: rng() * TAU });
    for (let i = 0; i < 22; i++) this.motesNear.push({ x: rng() * W, y: rng() * H, r: 2 + rng() * 2.4, s: 14 + rng() * 18, ph: rng() * TAU });
    this._bgGrad = null;
  },

  emit(type, data) {
    if (typeof this.game.event === 'function') {
      this.game.event(type, data);
    } else {
      const store = (window.__GF_EVENTS__ = window.__GF_EVENTS__ || []);
      const rec = { type: type, t: this.game.time };
      for (const k in data) rec[k] = data[k];
      store.push(rec);
    }
  },

  reset() {
    const g = this.game;
    if (this.terminalSeen) {
      this.emit('run_restarted', { nodesBefore: this.terminalNodes, nodesAfter: 0 });
      this.terminalSeen = false;
    }
    this.player = { x: 480, y: 270, r: 11, kx: 0, ky: 0 };
    this.trail = [];
    this.pressure = 100;
    this.nodesActivated = 0;
    this.nodes = [
      { x: 700, y: 270, active: false, bloom: 0 },
      { x: 350, y: 522, active: false, bloom: 0 },
      { x: 94, y: 250, active: false, bloom: 0 }
    ];
    this.thorns = [
      { x: 180, y: 150, vx: 62, vy: 44, r: 14, rot: 0 },
      { x: 780, y: 440, vx: -54, vy: 58, r: 14, rot: 0 }
    ];
    this.thornBase = 70;
    this.hazardStep = 0;
    this.invuln = 0;
    this.lure = null;
    this.moveEvtTimer = 0;
    this.lastX = 480;
    this.tickTimer = 0;
    this.pulseTimer = 0.5;
    this.terminalSeen = false;
    this.terminalNodes = 0;
    g.time = 0;
    GF.Sfx.melody([[262, 0.09], [392, 0.09], [523, 0.16]], { type: 'sine', vol: 0.22 });
  },

  activate(n) {
    const g = this.game;
    const nb = this.nodesActivated;
    this.nodesActivated = nb + 1;
    n.active = true;
    n.bloom = 1;
    g.addScore(100);
    this.pressure = Math.min(100, this.pressure + 8);
    g.hitStop(0.06);
    g.flash('#3ef2c0', 0.35);
    g.shake(3, 0.25);
    g.burst(n.x, n.y, { count: 28, speed: 190, size: 4, life: 0.9, colors: ['#ffd166', '#3ef2c0', '#bffcf0'], gravity: 30 });
    GF.Sfx.melody([[523, 0.09], [659, 0.09], [784, 0.12], [1046, 0.2]], { type: 'triangle', vol: 0.4 });
    this.emit('node_activated', { nodesBefore: nb, nodesAfter: nb + 1 });
    if (this.thorns.length < 3) {
      this.thorns.push({ x: 480, y: 130, vx: 70, vy: 52, r: 14, rot: 0 });
      g.burst(480, 130, { count: 10, speed: 90, size: 3, life: 0.5, colors: ['#c2455f', '#ff8fa3'], gravity: 0 });
    }
    if (this.nodesActivated >= 3) {
      this.terminalSeen = true;
      this.terminalNodes = 3;
      this.emit('state_reached', { state: 'success' });
      g.win({ message: 'GARDEN RESTORED' });
    }
  },

  update(dt) {
    const g = this.game, p = this.player, k = g.input.keys;
    this.pressure = Math.max(0, this.pressure - dt * DRAIN);
    const dep = 100 - this.pressure;
    const step = Math.min(12, Math.floor(dep / 8));
    if (step > this.hazardStep) {
      const sb = +(this.thornBase * (1 + 0.15 * this.hazardStep)).toFixed(2);
      const sa = +(this.thornBase * (1 + 0.15 * step)).toFixed(2);
      this.emit('hazard_speed_up', { speedBefore: sb, speedAfter: sa });
      this.hazardStep = step;
    }
    const f = 1 + 1.5 * (dep / 100);

    let mx = 0, my = 0;
    if (k.ArrowLeft || k.KeyA) mx -= 1;
    if (k.ArrowRight || k.KeyD) mx += 1;
    if (k.ArrowUp || k.KeyW) my -= 1;
    if (k.ArrowDown || k.KeyS) my += 1;
    if (mx || my) {
      const l = Math.hypot(mx, my) || 1;
      p.x += (mx / l) * 265 * dt;
      p.y += (my / l) * 265 * dt;
      this.lure = null;
    } else if (this.lure) {
      const dx = this.lure.x - p.x, dy = this.lure.y - p.y, d = Math.hypot(dx, dy);
      if (d < 14) this.lure = null;
      else { p.x += (dx / d) * 175 * dt; p.y += (dy / d) * 175 * dt; }
    }
    p.x += p.kx * dt; p.y += p.ky * dt;
    const dec = Math.pow(0.002, dt);
    p.kx *= dec; p.ky *= dec;
    p.x = clamp(p.x, 18, 942);
    p.y = clamp(p.y, 82, 522);

    this.trail.push(p.x, p.y);
    if (this.trail.length > 72) this.trail.splice(0, 2);

    this.moveEvtTimer += dt;
    if (this.moveEvtTimer > 0.15) {
      this.moveEvtTimer = 0;
      const xr = Math.round(p.x);
      if (Math.abs(xr - this.lastX) >= 1) {
        this.emit('player_moved', { before: this.lastX, after: xr });
        this.lastX = xr;
      }
    }

    if (g.input.pointer.clicked) {
      this.lure = { x: clamp(g.input.pointer.x, 18, 942), y: clamp(g.input.pointer.y, 82, 522) };
    }

    if (g.input.pressed('Space') || g.input.pressed('Enter')) {
      for (const n of this.nodes) {
        if (!n.active && dist(p.x, p.y, n.x, n.y) < RING) {
          this.activate(n);
          break;
        }
      }
    }

    for (const th of this.thorns) {
      th.x += th.vx * f * dt; th.y += th.vy * f * dt; th.rot += dt * 2 * f;
      if (th.x < th.r) { th.x = th.r; th.vx = Math.abs(th.vx); }
      if (th.x > 960 - th.r) { th.x = 960 - th.r; th.vx = -Math.abs(th.vx); }
      if (th.y < 82 + th.r) { th.y = 82 + th.r; th.vy = Math.abs(th.vy); }
      if (th.y > 540 - th.r) { th.y = 540 - th.r; th.vy = -Math.abs(th.vy); }
      if (this.invuln <= 0 && dist(p.x, p.y, th.x, th.y) < th.r + p.r) {
        this.pressure = Math.max(0, this.pressure - 10);
        this.invuln = 0.9;
        const dx = p.x - th.x, dy = p.y - th.y, d = Math.hypot(dx, dy) || 1;
        p.kx = (dx / d) * 260; p.ky = (dy / d) * 260;
        g.shake(5, 0.3);
        g.burst(p.x, p.y, { count: 14, speed: 150, size: 3, life: 0.5, colors: ['#ff6b81', '#7a2033', '#0e2233'], gravity: 60 });
        GF.Sfx.noise({ dur: 0.16, vol: 0.35, freq: 900 });
        GF.Sfx.beep({ freq: 140, to: 70, dur: 0.2, type: 'sawtooth', vol: 0.25 });
      }
    }
    this.invuln = Math.max(0, this.invuln - dt);
    for (const n of this.nodes) if (n.bloom > 0) n.bloom = Math.max(0, n.bloom - dt * 1.2);

    for (const arr of [this.motesFar, this.motesNear]) {
      for (const m of arr) {
        m.y -= m.s * dt;
        m.x += Math.sin(g.time * 0.7 + m.ph) * 9 * dt;
        if (m.y < -6) { m.y = 546; m.x = Math.random() * 960; }
        if (m.x < -6) m.x = 966; if (m.x > 966) m.x = -6;
      }
    }

    if (this.pressure < 20 && this.pressure > 0) {
      this.tickTimer -= dt;
      if (this.tickTimer <= 0) {
        this.tickTimer = 1;
        GF.Sfx.beep({ freq: 880, dur: 0.06, type: 'sine', vol: 0.14 });
      }
    }
    this.pulseTimer -= dt;
    if (this.pulseTimer <= 0) {
      this.pulseTimer = 1.25 - 0.8 * (1 - this.pressure / 100);
      GF.Sfx.beep({ freq: 110, to: 88, dur: 0.5, type: 'sine', vol: 0.1 });
    }

    if (this.pressure <= 0 && g.state === 'playing') {
      this.terminalSeen = true;
      this.terminalNodes = this.nodesActivated;
      this.emit('state_reached', { state: 'failure' });
      g.gameOver({ message: 'STORM PRESSURE EXHAUSTED' });
    }
  },

  draw(ctx) {
    const g = this.game, t = g.time, p = this.player;
    if (!this._bgGrad) {
      const gr = ctx.createRadialGradient(480, 280, 60, 480, 280, 580);
      gr.addColorStop(0, '#0e2233');
      gr.addColorStop(1, '#050b14');
      this._bgGrad = gr;
    }
    ctx.fillStyle = this._bgGrad;
    ctx.fillRect(0, 0, 960, 540);

    ctx.lineWidth = 1.5;
    for (const v of this.veins) {
      let boost = 0;
      for (const n of this.nodes) if (n.active) boost = Math.max(boost, 1 - dist(v.pts[0][0], v.pts[0][1], n.x, n.y) / 320);
      boost = clamp(boost, 0, 1);
      const a = 0.05 + 0.05 * Math.sin(t * 1.4 + v.phase) + boost * 0.22;
      ctx.strokeStyle = 'rgba(62,242,192,' + a.toFixed(3) + ')';
      ctx.beginPath();
      ctx.moveTo(v.pts[0][0], v.pts[0][1]);
      for (let i = 1; i < v.pts.length; i++) ctx.lineTo(v.pts[i][0], v.pts[i][1]);
      ctx.stroke();
    }

    ctx.fillStyle = 'rgba(62,242,192,0.16)';
    for (const m of this.motesFar) { ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, TAU); ctx.fill(); }

    for (const n of this.nodes) {
      if (!n.active) continue;
      const gg = ctx.createRadialGradient(n.x, n.y, 10, n.x, n.y, 170);
      gg.addColorStop(0, 'rgba(255,209,102,0.14)');
      gg.addColorStop(1, 'rgba(255,209,102,0)');
      ctx.fillStyle = gg;
      ctx.beginPath(); ctx.arc(n.x, n.y, 170, 0, TAU); ctx.fill();
    }

    for (const n of this.nodes) {
      const pulse = 0.5 + 0.5 * Math.sin(t * 2 + n.x * 0.01);
      if (n.active) { ctx.strokeStyle = 'rgba(255,209,102,0.9)'; ctx.lineWidth = 3; }
      else { ctx.strokeStyle = 'rgba(255,209,102,' + (0.25 + 0.2 * pulse).toFixed(3) + ')'; ctx.lineWidth = 2; }
      ctx.setLineDash([14, 10]);
      ctx.lineDashOffset = -t * 24;
      ctx.beginPath(); ctx.arc(n.x, n.y, RING, 0, TAU); ctx.stroke();
      ctx.setLineDash([]);
      const cr = n.active ? 12 : 8 + 3 * pulse;
      const cg = ctx.createRadialGradient(n.x, n.y, 0, n.x, n.y, cr * 3);
      cg.addColorStop(0, n.active ? 'rgba(255,209,102,0.95)' : 'rgba(255,209,102,0.5)');
      cg.addColorStop(1, 'rgba(255,209,102,0)');
      ctx.fillStyle = cg;
      ctx.beginPath(); ctx.arc(n.x, n.y, cr * 3, 0, TAU); ctx.fill();
      ctx.fillStyle = n.active ? '#ffe9b0' : '#ffd166';
      ctx.beginPath(); ctx.arc(n.x, n.y, cr * 0.55, 0, TAU); ctx.fill();
      if (n.bloom > 0) {
        ctx.strokeStyle = 'rgba(255,209,102,' + (n.bloom * 0.8).toFixed(3) + ')';
        ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(n.x, n.y, RING + (1 - n.bloom) * 100, 0, TAU); ctx.stroke();
      }
    }

    if (g.state === 'playing') {
      for (const n of this.nodes) {
        if (!n.active && dist(p.x, p.y, n.x, n.y) < RING) {
          GF.Draw.text(ctx, 'PRESS SPACE', n.x, clamp(n.y - RING - 16, 100, 520), { size: 14, color: '#ffe9b0', weight: '800' });
          break;
        }
      }
    }

    for (let i = 0; i < this.trail.length; i += 2) {
      const kk = i / this.trail.length;
      ctx.globalAlpha = kk * 0.35;
      ctx.fillStyle = '#3ef2c0';
      ctx.beginPath(); ctx.arc(this.trail[i], this.trail[i + 1], 1 + kk * 5, 0, TAU); ctx.fill();
    }
    ctx.globalAlpha = 1;

    for (const th of this.thorns) {
      ctx.save();
      ctx.translate(th.x, th.y);
      ctx.rotate(th.rot);
      ctx.fillStyle = '#c2455f';
      ctx.beginPath();
      for (let i = 0; i < 8; i++) {
        const a = (i / 8) * TAU;
        ctx.lineTo(Math.cos(a) * th.r * 1.6, Math.sin(a) * th.r * 1.6);
        ctx.lineTo(Math.cos(a + TAU / 16) * th.r * 0.7, Math.sin(a + TAU / 16) * th.r * 0.7);
      }
      ctx.closePath(); ctx.fill();
      ctx.fillStyle = '#ff8fa3';
      ctx.beginPath(); ctx.arc(0, 0, th.r * 0.55, 0, TAU); ctx.fill();
      ctx.fillStyle = '#2a0a12';
      ctx.beginPath(); ctx.arc(0, 0, th.r * 0.25, 0, TAU); ctx.fill();
      ctx.restore();
    }

    const blink = this.invuln > 0 && Math.floor(this.invuln * 12) % 2 === 0;
    if (!blink) {
      const pg = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, 26);
      pg.addColorStop(0, 'rgba(62,242,192,0.9)');
      pg.addColorStop(1, 'rgba(62,242,192,0)');
      ctx.fillStyle = pg;
      ctx.beginPath(); ctx.arc(p.x, p.y, 26, 0, TAU); ctx.fill();
      ctx.fillStyle = '#eafff8';
      ctx.beginPath(); ctx.arc(p.x, p.y, 7, 0, TAU); ctx.fill();
      ctx.strokeStyle = 'rgba(62,242,192,0.8)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(p.x, p.y, 12, 0, TAU); ctx.stroke();
    }

    if (this.lure) {
      ctx.strokeStyle = 'rgba(191,252,240,0.35)';
      ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(this.lure.x, this.lure.y, 10 + 3 * Math.sin(t * 5), 0, TAU); ctx.stroke();
    }

    ctx.fillStyle = 'rgba(255,255,255,0.5)';
    for (const m of this.motesNear) { ctx.beginPath(); ctx.arc(m.x, m.y, m.r, 0, TAU); ctx.fill(); }

    GF.Draw.vignette(ctx, 960, 540, 0.4);
    if (this.pressure < 20 && g.state === 'playing') {
      const a = 0.1 + 0.08 * Math.sin(t * 6);
      const rg = ctx.createRadialGradient(480, 280, 200, 480, 280, 580);
      rg.addColorStop(0, 'rgba(255,60,90,0)');
      rg.addColorStop(1, 'rgba(255,60,90,' + a.toFixed(3) + ')');
      ctx.fillStyle = rg;
      ctx.fillRect(0, 0, 960, 540);
    }

    GF.Draw.text(ctx, 'SIGNAL NODES', 22, 22, { size: 12, color: '#7fd8c4', align: 'left', weight: '800' });
    for (let i = 0; i < 3; i++) {
      ctx.beginPath(); ctx.arc(30 + i * 26, 44, 8, 0, TAU);
      if (this.nodes[i] && this.nodes[i].active) { ctx.fillStyle = '#ffd166'; ctx.fill(); }
      else { ctx.strokeStyle = 'rgba(62,242,192,0.6)'; ctx.lineWidth = 2; ctx.stroke(); }
    }
    GF.Draw.text(ctx, this.nodesActivated + '/3', 114, 44, { size: 14, color: '#eafff8', align: 'left', weight: '800' });
    GF.Draw.text(ctx, 'SCORE', 480, 20, { size: 12, color: 'rgba(255,255,255,0.6)', weight: '700' });
    GF.Draw.text(ctx, 'STORM PRESSURE', 938, 52, { size: 12, color: '#7fd8c4', align: 'right', weight: '800' });
    GF.Draw.roundRect(ctx, 698, 62, 240, 14, 7, '#0e2233');
    const pw = 240 * (this.pressure / 100);
    const pc = this.pressure > 40 ? '#3ef2c0' : this.pressure > 20 ? '#ffd166' : '#ff6b81';
    if (pw > 3) GF.Draw.roundRect(ctx, 698, 62, pw, 14, 7, pc);
    GF.Draw.text(ctx, String(Math.ceil(this.pressure)), 690, 69, { size: 13, color: '#eafff8', align: 'right', weight: '800' });

    if (t < 6 && g.state === 'playing') {
      ctx.globalAlpha = clamp(6 - t, 0, 1) * 0.85;
      GF.Draw.text(ctx, 'Glide into a node ring and press SPACE to attune the signal', 480, 514, { size: 16, color: '#9fe8d8', weight: '600' });
      ctx.globalAlpha = 1;
    }
  }
};

game.add('play', play);
game.titleScreen({
  subtitle: 'WASD / Arrows to glide  ·  SPACE attunes nodes  ·  press any key',
  onStart: () => game.go('play')
});
})();
